/* User-initiated Google Identity Services reads. No provider credentials or event cache on disk. */
(function(root){'use strict';
const scopes=['https://www.googleapis.com/auth/gmail.readonly'];
let token=null,expiry=0,version=0,loading=null;
function clear(){token=null;expiry=0;version++;if(typeof allowed!=='undefined')allowed=new Set();}
function ready(){return !!token&&Date.now()<expiry;}
function library(){if(root.google?.accounts?.oauth2)return Promise.resolve();if(loading)return loading;loading=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://accounts.google.com/gsi/client';s.async=true;s.onload=()=>root.google?.accounts?.oauth2?resolve():reject(Error('Google sign-in did not load.'));s.onerror=()=>{loading=null;s.remove();reject(Error('Could not load Google sign-in. Check your connection and try again.'));};document.head.append(s);});return loading;}
function authorize(clientId){if(!/^[\w-]+\.apps\.googleusercontent\.com$/.test(clientId))return Promise.reject(Error('Gmail connection needs its Google OAuth application setup.'));if(!root.google?.accounts?.oauth2)return Promise.reject(Error('Google sign-in is loading. Click Connect again when it is ready.'));clear();const generation=version;return new Promise((resolve,reject)=>{let settled=false;const fail=message=>{if(!settled){settled=true;reject(Error(message));}};const client=root.google.accounts.oauth2.initTokenClient({client_id:clientId,scope:scopes.join(' '),include_granted_scopes:false,callback:r=>{if(generation!==version)return fail('Connection was cancelled.');if(r.error||!r.access_token)return fail('Google did not grant Gmail access. You can try again.');if(!root.google.accounts.oauth2.hasGrantedAllScopes(r,...scopes))return fail('Gmail read access is needed.');token=r.access_token;expiry=Date.now()+Math.max(0,Number(r.expires_in||0)-30)*1000;settled=true;resolve();},error_callback:e=>fail(e.type==='popup_closed'?'Google sign-in was closed. No connection was made.':'Google could not open sign-in. Allow the sign-in popup and try again.')});client.requestAccessToken({prompt:'select_account'});});}
async function get(path,params,generation=version){if(!ready()){clear();throw Error('Gmail is not connected or its session expired. Connect again to refresh.');}const url=new URL('https://gmail.googleapis.com/gmail/v1/users/me/'+path);for(const [k,v] of Object.entries(params||{})){if(Array.isArray(v))for(const item of v)url.searchParams.append(k,String(item));else url.searchParams.set(k,String(v));}const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);let response;try{response=await fetch(url,{headers:{Authorization:'Bearer '+token},signal:controller.signal,cache:'no-store',credentials:'omit',referrerPolicy:'no-referrer'});}catch(e){throw Error(e.name==='AbortError'?'Gmail request timed out. Try Refresh again.':'Could not reach Gmail. Existing results are stale.');}finally{clearTimeout(timer);}if(generation!==version)throw Error('Gmail session changed.');if(response.status===401){clear();throw Error('Google session expired. Connect again.');}if(response.status===403)throw Error('Google denied this read. Check Gmail API enablement and the permissions granted to WAM.');if(response.status===429)throw Error('Google is limiting requests. Wait a little before Refresh.');if(!response.ok)throw Error('Gmail read failed ('+response.status+'). Try again.');const body=await response.text();if(body.length>2000000)throw Error('This email response is too large for the bounded reader. Open it in Gmail instead.');return JSON.parse(body);}
let allowed=new Set();
async function profile(){const p=await get('profile',{fields:'emailAddress'});return typeof p.emailAddress==='string'?p.emailAddress:'Connected Gmail account';}
async function recent(query=''){
 allowed=new Set();if(typeof query!=='string'||query.length>300)throw Error('Keep the email search under 300 characters.');
 const q='newer_than:14d -in:trash -in:spam'+(query.trim()?' ('+query.trim()+')':'');const generation=version;
 const data=await get('messages',{q,maxResults:40,includeSpamTrash:false,fields:'messages(id),nextPageToken,resultSizeEstimate'},generation),ids=(data.messages||[]).map(m=>m.id).filter(id=>typeof id==='string'&&/^[a-zA-Z0-9_-]{1,200}$/.test(id)).slice(0,40),items=[];
 for(let i=0;i<ids.length;i+=4){const batch=await Promise.all(ids.slice(i,i+4).map(id=>get('messages/'+encodeURIComponent(id),{format:'metadata',metadataHeaders:['Subject','From','Date'],fields:'id,threadId,snippet,internalDate,payload(headers)'},generation)));items.push(...batch);}
 if(generation!==version)throw Error('Gmail session changed.');const earliest=Date.now()-14*86400000;const filtered=items.filter(m=>Number(m.internalDate)>=earliest&&Number(m.internalDate)<=Date.now());allowed=new Set(filtered.map(m=>m.id));return {items:filtered,truncated:!!data.nextPageToken};
}
async function selected(ids){if(!Array.isArray(ids)||!ids.length||ids.length>10||new Set(ids).size!==ids.length||ids.some(id=>!allowed.has(id)))throw Error('Select between one and ten messages from the current results.');const generation=version,items=[];for(let i=0;i<ids.length;i+=2)items.push(...await Promise.all(ids.slice(i,i+2).map(id=>get('messages/'+encodeURIComponent(id),{format:'full',fields:'id,threadId,snippet,internalDate,payload'},generation))));if(generation!==version)throw Error('Gmail session changed.');return items;}
function disconnect(){const previous=token;clear();if(previous&&root.google?.accounts?.oauth2)root.google.accounts.oauth2.revoke(previous,()=>{});root.dispatchEvent?.(new Event('wam:google-revoked'));}
root.addEventListener?.('wam:google-revoked',clear);
root.WamGoogleGmail={library:()=>root.WamGoogleCalendar.library(),authorize,profile,recent,selected,disconnect,ready,scopes};
})(window);
